pub fn parse_count<I>(args: I) -> i32
where
    I: IntoIterator<Item = String>,
{
    let mut args = args.into_iter();
    let _program_name = args.next();

    match args.next().as_deref() {
        Some("--a") => {
            let raw_value = args.next().expect("missing value for --a");
            parse_cpp_stoi(&raw_value)
        }
        _ => 14,
    }
}

fn parse_cpp_stoi(input: &str) -> i32 {
    let bytes = input.as_bytes();
    let mut index = 0usize;

    while index < bytes.len() && is_c_whitespace(bytes[index]) {
        index += 1;
    }

    let sign = match bytes.get(index) {
        Some(b'+') => {
            index += 1;
            1i64
        }
        Some(b'-') => {
            index += 1;
            -1i64
        }
        _ => 1i64,
    };

    let digits_start = index;
    let max_magnitude = if sign < 0 {
        i32::MAX as i64 + 1
    } else {
        i32::MAX as i64
    };

    let mut magnitude = 0i64;
    while let Some(byte) = bytes.get(index) {
        if !byte.is_ascii_digit() {
            break;
        }

        let digit = (byte - b'0') as i64;
        magnitude = magnitude
            .checked_mul(10)
            .and_then(|value| value.checked_add(digit))
            .expect("stoi out of range");

        if magnitude > max_magnitude {
            panic!("stoi out of range");
        }

        index += 1;
    }

    if index == digits_start {
        panic!("invalid stoi argument");
    }

    let value = magnitude * sign;
    if value < i32::MIN as i64 || value > i32::MAX as i64 {
        panic!("stoi out of range");
    }

    value as i32
}

fn is_c_whitespace(byte: u8) -> bool {
    matches!(byte, b' ' | b'\n' | b'\r' | b'\t' | 0x0b | 0x0c)
}

