use std::collections::HashMap;
use std::hash::Hash;

#[derive(Debug, Clone)]
pub struct HopscotchMap<K, V> {
    inner: HashMap<K, V>,
}

impl<K, V> HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    pub fn new() -> Self {
        Self {
            inner: HashMap::new(),
        }
    }

    pub fn insert(&mut self, key: K, value: V) {
        self.inner.insert(key, value);
    }
}

impl<K, V> HopscotchMap<K, V>
where
    K: Eq + Hash,
    V: Default,
{
    pub fn index_mut_or_default(&mut self, key: K) -> &mut V {
        self.inner.entry(key).or_default()
    }
}

impl<K, V> PartialEq for HopscotchMap<K, V>
where
    K: Eq + Hash,
    V: PartialEq,
{
    fn eq(&self, other: &Self) -> bool {
        self.inner == other.inner
    }
}

impl<K, V> Eq for HopscotchMap<K, V>
where
    K: Eq + Hash,
    V: Eq,
{
}

